interrupt-worker:
var ready=new java.util.concurrent.LinkedBlockingQueue<String>(); ready.add("work");
assertEquals("work",QueueWorker.nextOrStopped(ready));
var stopped=new java.util.concurrent.atomic.AtomicReference<String>(); var interrupted=new java.util.concurrent.atomic.AtomicBoolean();
var started=new java.util.concurrent.CountDownLatch(1);
var worker=new Thread(() -> { started.countDown(); stopped.set(QueueWorker.nextOrStopped(ready)); interrupted.set(Thread.currentThread().isInterrupted()); });
worker.start();
try { assertTrue(started.await(2,java.util.concurrent.TimeUnit.SECONDS)); worker.interrupt(); worker.join(2000); assertFalse(worker.isAlive()); assertEquals("stopped",stopped.get()); assertTrue(interrupted.get()); }
finally { worker.interrupt(); worker.join(2000); }

